package com.bank.lifecycle.aggregation;

import java.util.ArrayList;
import java.util.List;

public class Branch {
    private final String branchCode;
    private final String branchName;
    private final List<Employee> employees = new ArrayList<>();

    public Branch(String branchCode, String branchName) {
        this.branchCode = branchCode;
        this.branchName = branchName;
    }

    // Branch does NOT create employees — they are added from outside
    public void addEmployee(Employee emp) {
        employees.add(emp);
    }

    public void removeEmployee(Employee emp) {
        employees.remove(emp);
    }

    // Branch closed → employees SURVIVE (returned for transfer)
    public List<Employee> close() {
        List<Employee> survivingEmployees = new ArrayList<>(employees);
        employees.clear();  // branch no longer references them
        return survivingEmployees;  // ALIVE! Ready for another branch.
    }

    public String getBranchCode() { return branchCode; }
    public String getBranchName() { return branchName; }
    public List<Employee> getEmployees() { return List.copyOf(employees); }
    public int getEmployeeCount() { return employees.size(); }
