// COMPOSITION: Loan OWNS EMIs — EMIs die with the loan
package com.bank.lifecycle.composition;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

public class Loan {
    private final String loanId;
    private final BigDecimal principal;
    private final int tenureMonths;
    private final List<EMI> emis = new ArrayList<>();  // OWNED — created by Loan
    private String status;

    public Loan(String loanId, BigDecimal principal, int tenureMonths, BigDecimal annualRate) {
        this.loanId = loanId;
        this.principal = principal;
        this.tenureMonths = tenureMonths;
        this.status = "ACTIVE";
        // Loan CREATES its EMIs — composition!
        generateEMIs(annualRate);
    }

    private void generateEMIs(BigDecimal annualRate) {
        BigDecimal monthlyRate = annualRate.divide(BigDecimal.valueOf(12), 6, RoundingMode.HALF_UP);
        BigDecimal emiAmount = principal.multiply(monthlyRate)
            .divide(BigDecimal.ONE.subtract(
                BigDecimal.ONE.add(monthlyRate).pow(-tenureMonths)), 2, RoundingMode.HALF_UP);
        // Simplified: equal EMIs
        BigDecimal simpleEmi = principal.divide(BigDecimal.valueOf(tenureMonths), 2, RoundingMode.HALF_UP);

        for (int i = 1; i <= tenureMonths; i++) {
            emis.add(new EMI(loanId + "-EMI-" + String.format("%03d", i), i, simpleEmi));
        }
    }

    // Loan closed → ALL EMIs marked closed (composition: children's fate bound to parent)
    public void close() {
        status = "CLOSED";
        emis.forEach(EMI::markClosed);
        // In JPA with cascade + orphanRemoval: deleting Loan → deletes all EMI rows
    }

    public void payEMI(int month) {
        emis.stream()
            .filter(e -> e.getMonth() == month && "PENDING".equals(e.getStatus()))
            .findFirst()
            .ifPresent(EMI::markPaid);
    }

    public String getLoanId() { return loanId; }
    public BigDecimal getPrincipal() { return principal; }
    public String getStatus() { return status; }
    public List<EMI> getEmis() { return List.copyOf(emis); }
    public long getPendingEMICount() {
        return emis.stream().filter(e -> "PENDING".equals(e.getStatus())).count();
    }
}
```

