// ─── File: src/test/java/com/bank/lifecycle/LifecycleTest.java ───
package com.bank.lifecycle;

import com.bank.lifecycle.aggregation.*;
import com.bank.lifecycle.composition.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class LifecycleTest {

    // ═══ AGGREGATION: children survive parent destruction ═══
    @Test
    void aggregation_employeesSurviveBranchClosure() {
        Employee rajesh = new Employee("E001", "Rajesh Kumar");
        Employee priya = new Employee("E002", "Priya Sharma");

        Branch cpBranch = new Branch("CP001", "Connaught Place");
        cpBranch.addEmployee(rajesh);
        cpBranch.addEmployee(priya);
        assertThat(cpBranch.getEmployeeCount()).isEqualTo(2);

        // Close the branch → employees SURVIVE!
        List<Employee> survivors = cpBranch.close();
        assertThat(cpBranch.getEmployeeCount()).isZero();  // branch empty
        assertThat(survivors).hasSize(2);                   // employees alive!
        assertThat(rajesh.getName()).isEqualTo("Rajesh Kumar");  // still exists!

        // Transfer to new branch:
        Branch npBranch = new Branch("NP001", "Nehru Place");
        survivors.forEach(npBranch::addEmployee);
        assertThat(npBranch.getEmployeeCount()).isEqualTo(2);  // transferred!
    }

    @Test
    void aggregation_employeeExistsWithoutBranch() {
        Employee rajesh = new Employee("E001", "Rajesh Kumar");
        // rajesh exists WITHOUT any branch — independent lifecycle!
        assertThat(rajesh.getName()).isEqualTo("Rajesh Kumar");
        // Aggregation: child is created OUTSIDE parent, exists independently.
    }

    // ═══ COMPOSITION: children die with parent ═══
    @Test
    void composition_emisCreatedByLoan() {
        Loan loan = new Loan("LOAN-001", new BigDecimal("1200000"), 12, new BigDecimal("0.09"));
        // Loan CREATES 12 EMIs in constructor — composition!
        assertThat(loan.getEmis()).hasSize(12);
        assertThat(loan.getEmis().get(0).getEmiId()).startsWith("LOAN-001-EMI-");
    }

    @Test
    void composition_emisDieWithLoanClosure() {
        Loan loan = new Loan("LOAN-001", new BigDecimal("1200000"), 12, new BigDecimal("0.09"));
        loan.payEMI(1);
        loan.payEMI(2);
        assertThat(loan.getPendingEMICount()).isEqualTo(10);

        // Close the loan → ALL EMIs closed (die with parent)
        loan.close();
        assertThat(loan.getStatus()).isEqualTo("CLOSED");
        assertThat(loan.getEmis()).allMatch(e -> "CLOSED".equals(e.getStatus()));
        // In JPA: cascade delete would remove all EMI rows from DB.
    }

    @Test
    void composition_emiMeaninglessWithoutLoan() {
        // Creating an EMI alone is technically possible but MEANINGLESS:
        EMI orphan = new EMI("ORPHAN-001", 1, new BigDecimal("100000"));
        // Which loan? What principal? What tenure? No context!
        // EMI has no meaning without its parent Loan — composition.
        assertThat(orphan.getEmiId()).isEqualTo("ORPHAN-001");  // exists but meaningless
    }

    // ═══ THE KEY DIFFERENCE: lifecycle ═══
    @Test
    void lifecycleDifference() {
        // AGGREGATION: parent destroyed → children SURVIVE
        Branch branch = new Branch("B001", "Test Branch");
        Employee emp = new Employee("E001", "Test");
        branch.addEmployee(emp);
        branch.close();
        assertThat(emp.getName()).isEqualTo("Test");  // ALIVE!

        // COMPOSITION: parent destroyed → children DESTROYED
        Loan loan = new Loan("L001", new BigDecimal("100000"), 6, new BigDecimal("0.09"));
        loan.close();
        assertThat(loan.getEmis()).allMatch(e -> "CLOSED".equals(e.getStatus()));  // ALL CLOSED!
    }
}
